import pytest

from bedrock_protocol import v827, v975, v1001, v2168

# generated by gophertunnel b8bd735:
# &packet.GameRulesChanged{GameRules: []protocol.GameRule{ {Name: "showcoordinates",
# CanBeModifiedByPlayer: true, Value: true}, {Name: "maxcommandchainlength", Value: uint32(131070)},
# {Name: "playerssleepingpercentage", CanBeModifiedByPlayer: true, Value: uint32(100)}}}
FIXED_INT = bytes.fromhex(
    "030f73686f77636f6f7264696e61746573010101156d6178636f6d6d616e64636861696e6c656e6774680002feff0100"
    "19706c6179657273736c656570696e6770657263656e74616765010264000000"
)

# generated by gophertunnel d6ce91a:
# &packet.GameRulesChanged{GameRules: []protocol.GameRule{ {Name: "showcoordinates",
# CanBeModifiedByPlayer: true, Value: true}, {Name: "maxcommandchainlength", Value: uint32(131070)},
# {Name: "playerssleepingpercentage", CanBeModifiedByPlayer: true, Value: uint32(100)}}}
VARINT_INT = bytes.fromhex(
    "030f73686f77636f6f7264696e61746573010101156d6178636f6d6d616e64636861696e6c656e6774680002feff07"
    "19706c6179657273736c656570696e6770657263656e74616765010264"
)

GOLDENS = [
    pytest.param(
        v2168.GameRulesChangedPacket(
            rule_data=v2168.GameRulesChangedPacketData(
                rules=[
                    v2168.GameRule(name="showcoordinates", can_be_modified_by_player=True, value=True),
                    v2168.GameRule(name="maxcommandchainlength", can_be_modified_by_player=False, value=131070),
                    v2168.GameRule(name="playerssleepingpercentage", can_be_modified_by_player=True, value=100),
                ]
            )
        ),
        FIXED_INT,
        id="v2168-fixed-int",
    ),
    pytest.param(
        v827.GameRulesChangedPacket(
            rule_data=v827.GameRulesChangedPacketData(
                rules=[
                    v827.GameRule(name="showcoordinates", can_be_modified_by_player=True, value=True),
                    v827.GameRule(name="maxcommandchainlength", can_be_modified_by_player=False, value=131070),
                    v827.GameRule(name="playerssleepingpercentage", can_be_modified_by_player=True, value=100),
                ]
            )
        ),
        VARINT_INT,
        id="v827-varint-int",
    ),
]


@pytest.mark.parametrize("version", [v975, v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_game_rules_changed_is_packet_72(version):
    assert version.PACKETS[72] is version.GameRulesChangedPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_game_rules_changed_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_game_rules_changed_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_game_rules_changed_is_one_shape_from_844():
    assert v975.GameRulesChangedPacket is v1001.GameRulesChangedPacket
    assert v1001.GameRulesChangedPacket is v2168.GameRulesChangedPacket


def test_game_rules_changed_before_844_is_a_shape_of_its_own():
    assert v827.GameRulesChangedPacket is not v2168.GameRulesChangedPacket


def test_the_integer_rule_is_four_bytes_wider_from_844_for_131070_and_100():
    assert len(VARINT_INT) + 4 == len(FIXED_INT)


def test_the_legacy_rule_is_a_shape_of_its_own():
    assert v1001.legacy.GameRule is not v2168.GameRule


def test_the_legacy_rule_is_one_byte_shorter_than_the_fixed_one():
    legacy = v1001.legacy.GameRule(name="maxcommandchainlength", can_be_modified_by_player=False, value=131070)
    fixed = v2168.GameRule(name="maxcommandchainlength", can_be_modified_by_player=False, value=131070)
    assert len(bytes(legacy)) + 1 == len(bytes(fixed))
